// A stand-in for the slice of @modelcontextprotocol/sdk the plugin touches,
// laid out at the real paths under the fixture DSH_HOME so the plugin's
// default path derivation resolves it. Records every request so tests assert
// on what actually went over the (pretend) wire. `connect`/`transport` mirror
// the SDK's Protocol surface; transports may carry the stdio server params the
// plugin reads at connect time.

export const requests = []

/** Every per-agent `callTool`, tagged with the client instance that made it. */
export const toolCalls = []

/** The client instances themselves, so a test can assert they were closed. */
export const clients = []

let clientSeq = 0

export const fixtureState = {
  failSessionStart: false,
  // Tools the per-agent connection advertises. A name absent here is refused by
  // the routing guard, which is what sends a call back to the shared client.
  listedTools: ['session_start', 'read_file', 'edit_file', 'write_file', 'daemon_info'],
  // Per-tool canned results, keyed by raw name.
  toolResults: {},
  // Make any non-session_start call fail at the transport level, to prove an
  // already-dispatched call is NOT retried on the shared connection.
  failToolCall: false,
  // Refusals to hand back, one per session_start, then success. Each entry is
  // the ENVELOPE plumb returns on a REFUSED declaration, which it carries under
  // result._meta['dev.plumbkit/error'] — a tool error is an ordinary JSON-RPC
  // response, not a transport failure, which is exactly the distinction the
  // plugin has to draw.
  sessionStartRefusals: []
}

export class Client {
  transport = null

  constructor (info) {
    this.info = info
    this.id = ++clientSeq
    this.closed = false
    clients.push(this)
  }

  async connect (transport) {
    this.transport = transport
    return {}
  }

  /** The per-agent connection's advertisement, consulted by the routing guard. */
  async listTools () {
    return { tools: fixtureState.listedTools.map((name) => ({ name })) }
  }

  /** A per-agent dispatch: the whole point of the mode under test. */
  async callTool (params, resultSchema, options) {
    toolCalls.push({
      clientId: this.id,
      name: params?.name,
      arguments: params?.arguments,
      hasSignal: options?.signal !== undefined
    })
    if (params?.name === 'session_start') {
      if (fixtureState.failSessionStart === true) throw new Error('stub transport refused')
      if (fixtureState.sessionStartRefusals.length > 0) {
        const envelope = fixtureState.sessionStartRefusals.shift()
        return { isError: true, content: [{ type: 'text', text: 'refused' }], _meta: { 'dev.plumbkit/error': envelope } }
      }
      return { isError: false, content: [{ type: 'text', text: 'declared' }] }
    }
    if (fixtureState.failToolCall === true) throw new Error('stub tool failure')
    const canned = fixtureState.toolResults[params?.name]
    if (canned !== undefined) return canned
    return { isError: false, content: [{ type: 'text', text: `per-agent ${params?.name}` }] }
  }

  async close () {
    this.closed = true
  }

  async request (request, resultSchema, options) {
    if (fixtureState.failSessionStart === true && request?.params?.name === 'session_start') {
      throw new Error('stub transport refused')
    }
    requests.push(JSON.parse(JSON.stringify(request)))
    if (request?.params?.name === 'session_start' && fixtureState.sessionStartRefusals.length > 0) {
      const envelope = fixtureState.sessionStartRefusals.shift()
      return { isError: true, content: [{ type: 'text', text: 'refused' }], _meta: { 'dev.plumbkit/error': envelope } }
    }
    const parsed = resultSchema?.parse !== undefined ? resultSchema.parse({ ok: true }) : { ok: true }
    return parsed
  }
}
